import{_ as a,o as t,c as l,a0 as o}from"./chunks/framework.DqMqoJl9.js";const _=JSON.parse('{"title":"集合","description":"","frontmatter":{},"headers":[],"relativePath":"algorithm/6-set.md","filePath":"algorithm/6-set.md","lastUpdated":1791573371000}'),r={name:"algorithm/6-set.md"};function i(s,e,d,c,n,h){return t(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="集合" tabindex="-1">集合 <a class="header-anchor" href="#集合" aria-label="Permalink to &quot;集合&quot;">​</a></h1><h2 id="_1-概念" tabindex="-1">1 概念 <a class="header-anchor" href="#_1-概念" aria-label="Permalink to &quot;1 概念&quot;">​</a></h2><p>集合是一种无序且唯一的数据结构，js 中有集合这种数据结构 Set</p><p>集合的常用操作：去重、判断某元素是否在集合中、求交集</p><h2 id="_2-javascript-中的-set" tabindex="-1">2 JavaScript 中的 Set <a class="header-anchor" href="#_2-javascript-中的-set" aria-label="Permalink to &quot;2 JavaScript 中的 Set&quot;">​</a></h2><h3 id="_2-1-概念" tabindex="-1">2.1 概念 <a class="header-anchor" href="#_2-1-概念" aria-label="Permalink to &quot;2.1 概念&quot;">​</a></h3><p>Set 是一个特殊的类型集合 —— “值的集合”（没有键），它的每一个值只能出现一次。</p><p>它的主要方法如下：</p><ul><li><code>new Set(iterable)</code> —— 创建一个 set，如果提供了一个 iterable 对象（通常是数组），将会从数组里面复制值到 set 中</li><li><code>set.add(value)</code> —— 添加一个值，返回 set 本身</li><li><code>set.delete(value)</code> —— 删除值，如果 value 在这个方法调用的时候存在则返回 true ，否则返回 false</li><li><code>set.has(value)</code> —— 如果 value 在 set 中，返回 true，否则返回 false</li><li><code>set.clear()</code> —— 清空 set</li><li><code>set.size</code> —— 返回元素个数</li></ul><blockquote><p>Set 主要特点是，重复使用同一个值调用 set.add(value) 并不会发生什么改变。这就是 Set 里面的每一个值只出现一次的原因</p></blockquote><h3 id="_2-2-set-迭代" tabindex="-1">2.2 Set 迭代 <a class="header-anchor" href="#_2-2-set-迭代" aria-label="Permalink to &quot;2.2 Set 迭代&quot;">​</a></h3><p>Map 中用于迭代的方法在 Set 中也同样支持：</p><ul><li><code>set.keys()</code> —— 遍历并返回所有的值（returns an iterable object for values）</li><li><code>set.values()</code> —— 与 <code>set.keys()</code> 作用相同，这是为了兼容 Map</li><li><code>set.entries()</code> —— 遍历并返回所有的实体（returns an iterable object for entries）<code>[value, value]</code>，它的存在也是为了兼容 Map</li></ul><h2 id="_3-实例" tabindex="-1">3 实例 <a class="header-anchor" href="#_3-实例" aria-label="Permalink to &quot;3 实例&quot;">​</a></h2><h3 id="_3-1-leetcode-349-两个数组的交集" tabindex="-1">3.1 leetcode 349 两个数组的交集 <a class="header-anchor" href="#_3-1-leetcode-349-两个数组的交集" aria-label="Permalink to &quot;3.1 leetcode 349 两个数组的交集&quot;">​</a></h3>',15)])])}const p=a(r,[["render",i]]);export{_ as __pageData,p as default};
